      "event_hook_check": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "seq": {
            "type": "integer",
            "minimum": 1
          },
          "at": {
            "$ref": "primitives.schema.json#/$defs/timestamp"
          },
          "type": {
            "const": "hook_check"
          },
          "step_id": {
            "$ref": "primitives.schema.json#/$defs/step_id"
          },
          "data": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "source": {
                "enum": [
                  "mcp_server",
                  "hook",
                  "code_execution",
                  "model"
                ]
              },
              "hook_id": {
                "enum": [
                  "BH-1",
                  "BH-2",
                  "BH-3",
                  "BH-4",
                  "BH-5"
                ]
              },
              "check": {
                "enum": [
                  "heartbeat",
                  "agent_type",
                  "foreground",
                  "ticket_prompt",
                  "gates_before_check",
                  "decision_before_step",
                  "protected_path",
                  "datafile_path",
                  "caller_context",
                  "run_open_at_stop"
                ]
              },
              "tool": {
                "anyOf": [
                  {
                    "type": "string",
                    "maxLength": 128
                  },
                  {
                    "type": "null"
                  }
                ]
              },
              "result": {
                "enum": [
                  "allow",
                  "deny"
                ]
              },
              "subject_fingerprint": {
                "anyOf": [
                  {
                    "$ref": "primitives.schema.json#/$defs/fingerprint"
                  },
                  {
                    "type": "null"
                  }
                ]
              },
              "cites": {
                "type": "array",
                "items": {
                  "type": "integer",
                  "minimum": 1
                },
                "maxItems": 50
              }
            },
            "required": [
              "source",
              "hook_id",
              "check",
              "tool",
              "result",
              "cites"
            ],
            "allOf": [
              {
                "if": {
                  "properties": {
                    "hook_id": {
                      "const": "BH-1"
                    }
                  },
                  "required": [
                    "hook_id"
                  ]
                },
                "then": {
                  "properties": {
                    "check": {
                      "enum": [
                        "heartbeat",
                        "agent_type",
                        "foreground",
                        "ticket_prompt",
                        "gates_before_check",
                        "decision_before_step"
                      ]
                    }
                  }
                }
              },
              {
                "if": {
                  "properties": {
                    "hook_id": {
                      "const": "BH-2"
                    }
                  },
                  "required": [
                    "hook_id"
                  ]
                },
                "then": {
                  "properties": {
                    "check": {
                      "enum": [
                        "heartbeat",
                        "protected_path",
                        "datafile_path",
                        "caller_context"
                      ]
                    }
                  }
                }
              },
              {
                "if": {
                  "properties": {
                    "hook_id": {
                      "const": "BH-3"
                    }
                  },
                  "required": [
                    "hook_id"
                  ]
                },
                "then": {
                  "properties": {
                    "check": {
                      "enum": [
                        "heartbeat"
                      ]
                    }
                  }
                }
              },
              {
                "if": {
                  "properties": {
                    "hook_id": {
                      "const": "BH-4"
                    }
                  },
                  "required": [
                    "hook_id"
                  ]
                },
                "then": {
                  "not": {}
                }
              },
              {
                "if": {
                  "properties": {
                    "hook_id": {
                      "const": "BH-5"
                    }
                  },
                  "required": [
                    "hook_id"
                  ]
                },
                "then": {
                  "properties": {
                    "check": {
                      "enum": [
                        "run_open_at_stop"
                      ]
                    }
                  }
                }
              },
              {
                "if": {
                  "properties": {
                    "check": {
                      "const": "heartbeat"
                    }
                  },
                  "required": [
                    "check"
                  ]
                },
                "then": {
                  "properties": {
                    "result": {
                      "const": "allow"
                    }
                  }
                }
              },
              {
                "if": {
                  "properties": {
                    "check": {
                      "const": "run_open_at_stop"
                    }
                  },
                  "required": [
                    "check"
                  ]
                },
                "then": {
                  "properties": {
                    "tool": {
                      "type": "null"
                    }
                  }
                }
              },
              {
                "if": {
                  "not": {
                    "properties": {
                      "check": {
                        "const": "run_open_at_stop"
                      }
                    },
                    "required": [
                      "check"
                    ]
                  }
                },
                "then": {
                  "properties": {
                    "tool": {
                      "type": "string",
                      "maxLength": 128
                    }
                  }
                }
              }
            ]
          }
        },
        "required": [
          "seq",
          "at",
          "type",
          "data"
        ]
      },
