  "cmd_inventory_v0_1": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://fairlead.heuris.com.au/contracts/kit/cmd_inventory_v0_1.schema.json",
    "title": "cmd_inventory_v0_1",
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "schema": {
        "const": "fairlead.kit.cmd_inventory/0.1"
      },
      "items": {
        "type": "array",
        "items": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "item_id": {
              "type": "string",
              "maxLength": 6,
              "pattern": "^i[0-9]{1,4}(?![\\s\\S])"
            },
            "kind": {
              "enum": [
                "reference",
                "quote",
                "number",
                "claim"
              ]
            },
            "paragraph_id": {
              "type": "string",
              "maxLength": 12,
              "pattern": "^(par)_[0-9a-f]{8}(?![\\s\\S])"
            },
            "text": {
              "type": "string",
              "maxLength": 1e3,
              "minLength": 1,
              "pattern": "\\S"
            },
            "source_ids": {
              "type": "array",
              "items": {
                "type": "string",
                "maxLength": 80,
                "pattern": "^[A-Za-z0-9_.:-]+(?![\\s\\S])"
              },
              "maxItems": 6,
              "uniqueItems": true
            },
            "value": {
              "anyOf": [
                {
                  "type": "string",
                  "maxLength": 40,
                  "minLength": 1,
                  "pattern": "[0-9]"
                },
                {
                  "type": "null"
                }
              ]
            }
          },
          "required": [
            "item_id",
            "kind",
            "paragraph_id",
            "text",
            "source_ids",
            "value"
          ],
          "allOf": [
            {
              "if": {
                "properties": {
                  "kind": {
                    "const": "number"
                  }
                },
                "required": [
                  "kind"
                ]
              },
              "then": {
                "properties": {
                  "value": {
                    "type": "string"
                  }
                }
              }
            },
            {
              "if": {
                "not": {
                  "properties": {
                    "kind": {
                      "const": "number"
                    }
                  },
                  "required": [
                    "kind"
                  ]
                }
              },
              "then": {
                "properties": {
                  "value": {
                    "type": "null"
                  }
                }
              }
            }
          ]
        },
        "maxItems": 600
      }
    },
    "required": [
      "schema",
      "items"
    ],
    "description": "Check my draft: what the extractor found in the person's draft, each item in the draft's own words and tied to its paragraph id. A number item's value is the number as the draft writes it."
  },
