                        "claim_id": {
                          "anyOf": [
                            {
                              "type": "string",
                              "maxLength": 12,
                              "pattern": "^(clm)_[0-9a-f]{8}(?![\\s\\S])"
                            },
                            {
                              "type": "null"
                            }
                          ]
                        },
