  "threshold_choices_v0_1": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://fairlead.heuris.com.au/contracts/kit/threshold_choices_v0_1.schema.json",
    "title": "threshold_choices_v0_1",
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "schema": {
        "const": "fairlead.kit.threshold_choices/0.1"
      },
      "decision_id": {
        "$ref": "https://fairlead.heuris.com.au/contracts/braids/v0.1/primitives.schema.json#/$defs/id_dec"
      },
      "rules": {
        "type": "array",
        "items": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "rule_id": {
              "type": "string",
              "maxLength": 64,
              "pattern": "^[a-z][a-z0-9_]{0,63}(?![\\s\\S])"
            },
            "choice": {
              "enum": [
                "default",
                "off",
                "own"
              ]
            },
            "min": {
              "type": [
                "number",
                "string",
                "boolean"
              ]
            },
            "max": {
              "type": [
                "number",
                "string",
                "boolean"
              ]
            },
            "equals": {
              "type": [
                "number",
                "string",
                "boolean"
              ]
            }
          },
          "required": [
            "rule_id",
            "choice"
          ],
          "allOf": [
            {
              "if": {
                "not": {
                  "properties": {
                    "choice": {
                      "const": "own"
                    }
                  },
                  "required": [
                    "choice"
                  ]
                }
              },
              "then": {
                "not": {
                  "anyOf": [
                    {
                      "required": [
                        "min"
                      ]
                    },
                    {
                      "required": [
                        "max"
                      ]
                    },
                    {
                      "required": [
                        "equals"
                      ]
                    }
                  ]
                }
              }
            },
            {
              "if": {
                "properties": {
                  "choice": {
                    "const": "own"
                  }
                },
                "required": [
                  "choice"
                ]
              },
              "then": {
                "oneOf": [
                  {
                    "required": [
                      "min"
                    ]
                  },
                  {
                    "required": [
                      "max"
                    ]
                  },
                  {
                    "required": [
                      "equals"
                    ]
                  }
                ]
              }
            }
          ]
        },
        "maxItems": 40
      }
    },
    "required": [
      "schema",
      "decision_id",
      "rules"
    ],
    "description": "Written by the server from a threshold card (dev ask 9): per pinned default, keep it, don't apply it, or the person's own single bound. The server builds the result_thresholds ports from the defaults and these answers; makers never write thresholds."
  },
